  "class Product:\n    def __init__(self, name, qty):\n        self.name = name\n        self.qty = qty\n\nclass Inventory:\n    def __init__(self):\n        self.products = []\n\n    def add(self, product):\n        self.products.append(product)\n\n    def find(self, name):\n        for p in self.products:\n            if p.name == name:\n                return p\n        return None\n\ninv = Inventory()\ninv.add(Product('Laptop', 5))\ninv.add(Product('Monitor', 12))\nprint(inv.find('Monitor').name)\nprint(inv.find('Tablet'))",
